// Package configschema exposes the service configuration schema generated by
// scripts/configref, so CLI checks can use the same required-variable lists the
// services enforce at startup.
package configschema

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
	"time"

	"github.com/Livepeer-FrameWorks/monorepo/pkg/config"
)

//go:embed config-schema.json
var raw []byte

// Variable is one configuration variable of a service command.
type Variable struct {
	Key         string `json:"key"`
	Type        string `json:"type"`
	Default     string `json:"default,omitempty"`
	Required    bool   `json:"required,omitempty"`
	Secret      bool   `json:"secret,omitempty"`
	Introduced  string `json:"introduced"`
	Deprecated  string `json:"deprecated,omitempty"`
	Replacement string `json:"replacement,omitempty"`
	Description string `json:"description"`
}

// Section is the configuration of one service command. Variant is empty for
// the server and names the subcommand otherwise.
type Section struct {
	Service   string     `json:"service"`
	Variant   string     `json:"variant,omitempty"`
	Command   string     `json:"command"`
	Variables []Variable `json:"variables"`
}

// Schema is the generated schema document.
type Schema struct {
	GeneratedBy string    `json:"generated_by"`
	Services    []Section `json:"services"`
}

// Load parses the embedded schema.
func Load() (Schema, error) {
	var s Schema
	if err := json.Unmarshal(raw, &s); err != nil {
		return Schema{}, fmt.Errorf("configschema: parse embedded schema: %w", err)
	}
	return s, nil
}

// Server returns the server configuration of a service, if the service has
// adopted typed configuration.
func (s Schema) Server(service string) (Section, bool) {
	for _, section := range s.Services {
		if section.Service == service && section.Variant == "" {
			return section, true
		}
	}
	return Section{}, false
}

// RequiredEnv lists the variables a service's server command requires at
// startup. It returns nil for a service the schema does not describe.
// Subcommand variants are not included; Missing checks those as well.
func (s Schema) RequiredEnv(service string) []string {
	section, ok := s.Server(service)
	if !ok {
		return nil
	}
	var keys []string
	for _, v := range section.Variables {
		if v.Required {
			keys = append(keys, v.Key)
		}
	}
	return keys
}

// Missing lists the required variables of every command of a service (the
// server and each subcommand variant) that env leaves unset, in schema order
// without duplicates. A blank or whitespace-only value counts as unset, as it
// does in the service loader. It returns nil for a service the schema does
// not describe.
func (s Schema) Missing(service string, env map[string]string) []string {
	var missing []string
	seen := map[string]bool{}
	for _, section := range s.Services {
		if section.Service != service {
			continue
		}
		for _, v := range section.Variables {
			if !v.Required || seen[v.Key] {
				continue
			}
			seen[v.Key] = true
			if strings.TrimSpace(env[v.Key]) == "" {
				missing = append(missing, v.Key)
			}
		}
	}
	return missing
}

// Invalid reports malformed supplied scalars and shared enums without echoing values.
func (s Schema) Invalid(service string, env map[string]string) []string {
	var invalid []string
	seen := map[string]bool{}
	for _, section := range s.Services {
		if section.Service != service {
			continue
		}
		for _, v := range section.Variables {
			raw := strings.TrimSpace(env[v.Key])
			if raw == "" || seen[v.Key] {
				continue
			}
			seen[v.Key] = true
			var err error
			switch v.Type {
			case "boolean":
				_, err = strconv.ParseBool(raw)
			case "integer":
				_, err = strconv.Atoi(raw)
			case "duration":
				_, err = time.ParseDuration(raw)
			}
			switch v.Key {
			case "LOG_LEVEL":
				if service != "helmsman" {
					err = (config.Logging{LogLevel: raw}).Validate()
				}
			case "GRPC_METADATA_POLICY":
				err = config.ValidateMetadataPolicy(raw)
			}
			if err != nil {
				invalid = append(invalid, v.Key)
			}
		}
	}
	return invalid
}
